-- Ad Mavericks One · Ranking radial crudo y normalizado
-- Ejecutar después de 00_raw_schema.sql; no convierte ranking en reach de campaña.

begin;

update public.source_workbooks
set is_current = false
where source_label = 'Ranking de radios Interviú'
  and id <> '1d9a2753-2977-5837-a3b3-1335e5bc665f'::uuid;

   NULL::date, NULL::date, '{"source":"Excel entregado por el usuario","sheets":[{"name":"Radios x Audiencia","rows":107,"columns":8},{"name":"Radios x Alcance","rows":107,"columns":8}],"metric_note":"Ranking contextual; no equivale automáticamente a reach de campaña."}'::jsonb)
on conflict (id) do update set
  file_name = excluded.file_name,
  sha256 = excluded.sha256,
  source_label = excluded.source_label,
  is_current = true,
  period_start = excluded.period_start,
  period_end = excluded.period_end,
  metadata = excluded.metadata,
  imported_at = now();

on conflict (workbook_id, sheet_name, source_row) do update set cells = excluded.cells;

delete from public.radio_station_metrics where workbook_id = '1d9a2753-2977-5837-a3b3-1335e5bc665f'::uuid;

on conflict (workbook_id, station_name) do update set genre = excluded.genre, dial = excluded.dial, frequency = excluded.frequency, rating = excluded.rating, share = excluded.share, rating_audience = excluded.rating_audience, reach_audience = excluded.reach_audience, reach_pct = excluded.reach_pct, exclusive_reach_pct = excluded.exclusive_reach_pct, audience_rank = excluded.audience_rank, reach_rank = excluded.reach_rank;

commit;
